{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values for stage 1 action selection.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_stickiness",
      "title": "Stage 1 Choice Stickiness",
      "description": "Adds a perseverance bonus to the stage 1 Q-value of the action chosen in the previous trial.",
      "params": [
        {
          "name": "stick_1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness_term_1 = np.zeros(2)\nif last_action_1 != -1:\n    stickiness_term_1[last_action_1] = stick_1\n    \nq1_scaled = beta_1 * q_stage1_net + stickiness_term_1",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_stickiness",
      "title": "Stage 2 Choice Stickiness",
      "description": "Adds a state-dependent perseverance bonus to the stage 2 Q-value of the action chosen in the previous visit to that state.",
      "params": [
        {
          "name": "stick_2",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness_term_2 = np.zeros(2)\nif last_action_2[state_idx] != -1:\n    stickiness_term_2[last_action_2[state_idx]] = stick_2\n\nq2_scaled = beta_2 * q_stage2_mf[state_idx] + stickiness_term_2",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the stage 1 model-free Q-value of the chosen action using the stage 2 reward prediction error.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the Q-values of all unchosen actions towards 0.5 at each trial.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_action_1 = 1 - action_1[trial]\nq_stage1_mf[unchosen_action_1] += decay_rate * (0.5 - q_stage1_mf[unchosen_action_1])\n\nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] += decay_rate * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    },
    {
      "name": "q_init_05",
      "title": "Neutral Q Initialization",
      "description": "Initializes all model-free Q-values to 0.5 instead of 0.",
      "params": [],
      "evidence": "q_stage1_mf = np.full(2, 0.5)\nq_stage2_mf = np.full((2, 2), 0.5)",
      "expressible_in_slots": true
    }
  ]
}
